import pandas as pd
import numpy as np
import json
from scipy.signal import find_peaks

def get_tga_data(file_path, sheet_name):
    df = pd.read_excel(file_path, sheet_name=sheet_name)

    # Identify columns based on the preview
    temp_col = "Temperature (°C)"
    weight_col = "Weight (%)"
    deriv_col = "Deriv. Weight (%/°C)"

    # Clean data: drop NaNs if any
    df = df.dropna(subset=[temp_col, weight_col, deriv_col])

    temps = df[temp_col].values
    weights = df[weight_col].values
    derivs = df[deriv_col].values

    return temps, weights, derivs

def main():
    file_path = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"
    sheet_name = "PVC"

    try:
        temps, weights, derivs = get_tga_data(file_path, sheet_name)

        # Find peaks in the derivative curve (DTG). 
        # DTG peaks correspond to maximum rate of mass loss (steepest descent in TGA).
        # We look for negative peaks (since mass is decreasing), so we invert the signal or use prominence.
        # The derivative values are negative during decomposition.
        # To find peaks using scipy, we can pass -derivs because find_peaks finds local maxima.

        inverted_derivs = -derivs

        # Use a reasonable distance and prominence to avoid noise.
        # PVC typically has two main stages: ~250-300°C (dehydrochlorination) and ~450-500°C (cracking).
        # Let's set parameters to find significant peaks.
        peaks, properties = find_peaks(inverted_derivs, prominence=0.1, distance=50)

        peak_temps = temps[peaks]
        peak_weights = weights[peaks]
        peak_derivs = derivs[peaks]

        # Prepare ECharts option
        # X-axis: Temperature
        # Y1: Weight (%)
        # Y2: Derivative Weight (%/°C)

        series_data_weight = [[float(t), float(w)] for t, w in zip(temps, weights)]
        series_data_deriv = [[float(t), float(d)] for t, d in zip(temps, derivs)]

        mark_points = []
        for i, pt in enumerate(peak_temps):
            # Get corresponding weight and deriv value at this temperature
            # Since temps might not be exactly unique integers, we rely on the index from find_peaks
            idx = peaks[i]
            w_val = weights[idx]
            d_val = derivs[idx]

            mark_points.append({
                "coord": [float(pt), float(w_val)],
                "value": f"{pt:.1f}°C",
                "symbolSize": 10,
                "itemStyle": {
                    "color": "#d62728"
                },
                "label": {
                    "show": True,
                    "formatter": "{b}",
                    "position": "top",
                    "fontSize": 12,
                    "color": "#d62728"
                }
            })

        option = {
            "title": {
                "text": f"PVC TGA Analysis ({sheet_name})",
                "left": "center",
                "textStyle": {
                    "fontFamily": "Noto Sans CJK KR",
                    "fontSize": 16
                }
            },
            "tooltip": {
                "trigger": "axis",
                "axisPointer": {
                    "type": "cross"
                }
            },
            "legend": {
                "data": ["Weight (%)", "Deriv. Weight (%/°C)"],
                "bottom": 0,
                "textStyle": {
                    "fontFamily": "Noto Sans CJK KR"
                }
            },
            "grid": {
                "left": "10%",
                "right": "10%",
                "bottom": "15%",
                "containLabel": True
            },
            "xAxis": {
                "type": "value",
                "name": "Temperature (°C)",
                "nameLocation": "middle",
                "nameGap": 30,
                "min": 30,
                "max": 900,
                "axisLabel": {
                    "formatter": "{value}"
                }
            },
            "yAxis": [
                {
                    "type": "value",
                    "name": "Weight (%)",
                    "position": "left",
                    "min": 0,
                    "max": 100,
                    "axisLine": {
                        "lineStyle": {
                            "color": "#1f77b4"
                        }
                    },
                    "splitLine": {
                        "lineStyle": {
                            "type": "dashed"
                        }
                    }
                },
                {
                    "type": "value",
                    "name": "Deriv. Weight (%/°C)",
                    "position": "right",
                    "axisLine": {
                        "lineStyle": {
                            "color": "#ff7f0e"
                        }
                    },
                    "splitLine": {
                        "show": False
                    }
                }
            ],
            "series": [
                {
                    "name": "Weight (%)",
                    "type": "line",
                    "smooth": True,
                    "showSymbol": False,
                    "lineStyle": {
                        "width": 2,
                        "color": "#1f77b4"
                    },
                    "data": series_data_weight,
                    "markPoint": {
                        "data": mark_points
                    }
                },
                {
                    "name": "Deriv. Weight (%/°C)",
                    "type": "line",
                    "smooth": True,
                    "showSymbol": False,
                    "yAxisIndex": 1,
                    "lineStyle": {
                        "width": 2,
                        "color": "#ff7f0e",
                        "type": "dashed"
                    },
                    "data": series_data_deriv
                }
            ]
        }

        figure = {
            "name": "pvc_tga_analysis",
            "option": option,
            "width": 614,
            "height": 442,
            "dpi": 300,
            "formats": ["png"]
        }

        output = {"figures": [figure]}
        print(json.dumps(output))

    except Exception as e:
        error_output = {"error": str(e)}
        print(json.dumps(error_output))

if __name__ == "__main__":
    main()
